import{S as a,o as d,c,a9 as s,B as n}from"./chunks/framework.DxG24V0C.js";const l=JSON.parse('{"title":"压缩 / 上下文注入 / 子代理：装配式的长会话扩展","description":"","frontmatter":{"title":"压缩 / 上下文注入 / 子代理：装配式的长会话扩展"},"headers":[],"relativePath":"deepseek/07-compaction-context-subagent.md","filePath":"deepseek/07-compaction-context-subagent.md","lastUpdated":1788319991000}'),r={name:"deepseek/07-compaction-context-subagent.md"},h=Object.assign(r,{setup(i){const o=[{question:"压缩（compaction）在 session 的模型历史上到底做了什么？",options:["把一段旧表面折叠成一个摘要节点","把全部内容从头删光","把消息顺序重新排一遍","用摘要把旧段逐条抹平"],correct:0,explanation:"压缩 = 用 surface `{op: replace}` 把 [start,end] 旧段折叠成一个摘要 user/message。其余三项（清空/重排/逐条抹平）都不符合一次 replace 的语义。"},{question:"为什么把压缩做成一个可换的缝（Service Definition + Provider）？",options:["不同产品的压策略差异大，做成缝便于可换","这样强制所有产品共用同一个后端","做成函数比缝省一层抽象","不换 provider 就无法触发压缩"],correct:0,explanation:"压缩是个 seam（Definition=ctx.compaction、Provider=basic 等、Consumer=/compact）。不同产品的压缩策略差异大，做成可换缝后换 provider 即可，loop 无需改。"},{question:"压缩事务的锁是怎么释放的？",options:["start 先落、end 后落，方便检测孤儿锁","end 先落、start 后落","锁不进日志，由内存变量单管","每次压缩都新建一个新锁"],correct:0,explanation:'锁属于事件：`compaction/start` 先、`compaction/end` 最后。崩溃留下的"有 start 无 end"在日志里可检测，无需另设状态机。'},{question:"`agent.inject()` 与 `agent.followup()` 的关键区别是？",options:["inject 排队上下文而不唤醒，followup 唤醒","两者都唤醒但程度不同","inject 直接改摘要，followup 改日志","两者都只清空 inbox"],correct:0,explanation:'inject = next-step 且 wakeup=false（补充信息、不打断），followup = next-turn 且唤醒=true（要求干活）。这是"补充背景" vs "触发响应"的区分。'},{question:"子代理缝和 bash 缝最大的不同是？",options:["subagent 允许多个 provider 并存","bash 允许多个并发执行器","subagent 不能跨产品委托","subagent 不承载任何能力"],correct:0,explanation:"子代理是 `ctx.subagents`——named provider 注册表，spawn/fork/acp/codex/claude-code 多者共存；而 bash 只允许一个 executor。"}];return(p,e)=>{const t=a("Quiz");return d(),c("div",null,[e[0]||(e[0]=s("",70)),n(t,{questions:o})])}}});export{l as __pageData,h as default};
